\label{Lemma 2.2} (\cite{Xin1}) Let $w_-<w_+$,
 $(\ref{(2.11)})$ has a unique smooth solution $w^r_\sigma(t,x)$
satisfying
\begin{enumerate}
\item[(1)] $w_-< w^r_\sigma(t,x)<w_+,~(w^r_\sigma)_x(t,x)\geq 0 $;

\item[(2)] For any $p$ $(1\leq p\leq +\infty)$, there exists a constant
$C$ such that
$$
\begin{array}{ll}
\| \frac{\partial}{\partial x}w^r_\sigma(t,\cdot)\|_{L^p(\mathbf{R})}\leq
C\min\big{\{}(w_+-w_-)\sigma^{-1+ 1/p},~
(w_+-w_-)^{1/p}t^{-1+1/p}\big{\}}, \\[2mm]
 \| \frac{\partial^2}{\partial x^2}w^r_\sigma(t,\cdot)\|_{L^p(\mathbf{R})}\leq
C\min\big{\{}(w_+-w_-)\sigma^{-2+ 1/p},~ \sigma^{-1+1/p}t^{-1}\big{\}};
\end{array}
$$
\item[(3)] If $ x-w_-t<0$ and $w_->0$, then
$$
\begin{array}{l}
 |w^r_\sigma(t,x)-w_-|\leq (w_+-w_-)e^{-\frac{2|x-w_-t|}{\sigma}},\\[2mm]
 |\frac{\partial}{\partial x}w^r_\sigma(t,\cdot)|\leq
\frac{2(w_+-w_-)}{\sigma}e^{-\frac{2|x-w_-t|}{\sigma}};
\end{array}
$$
 If $ x-w_+t> 0$ and $w_+<0$, then
$$
\begin{array}{l}
 |w^r_\sigma(t,x)-w_+|\leq (w_+-w_-)e^{-\frac{2|x-w_+t|}{\sigma}},\\[2mm]
 |\frac{\partial}{\partial x}w^r_\sigma(t,\cdot)|\leq
\frac{2(w_+-w_-)}{\sigma}e^{-\frac{2|x-w_+t|}{\sigma}};
\end{array}
$$

\item[(4)]$\sup\limits_{x\in\mathbf{R}} |w^r_\sigma(t,x)-w^r(\frac xt)|\leq
\min\big\{(w_+-w_-),\frac{\sigma}{t}[\ln(1+t)+|\ln\sigma|]\big\}$.
\end{enumerate}

\label{Lemma 2.3} The approximate rarefaction waves $(V^{R_i},
U^{R_i}, \Theta^{R_i})(t,x)~(i=1,3)$ constructed in \eqref{(2.12)}
have the following properties:
\begin{enumerate}
\item[(1)] $U^{R_i}_x(t,x)>0$ for $x\in \mathbf{R}$, $t>0$;
\item[(2)] For any $1\leq p\leq +\infty,$ the following estimates holds,
$$
\begin{array}{ll}
\|(V^{R_i},U^{R_i}, \Theta^{R_i})_x\|_{L^p(dx)} \leq
C(t+t_0)^{-1+\frac1p},\\
\|(V^{R_i},U^{R_i}, \Theta^{R_i})_{xx}\|_{L^p(dx)} \leq
C\sigma^{-1+\frac1p}(t+t_0)^{-1},\\
\|(V^{R_i},U^{R_i}, \Theta^{R_i})_{xxx}\|_{L^p(dx)} \leq
C\sigma^{-2+\frac1p}(t+t_0)^{-1},\\
\end{array}
$$
where the positive constant $C$ only depends on $p$ and the wave
strength;
\item[(3)] If $x\geq \lambda_{1+}(t+t_0)$, then
$$
\begin{array}{l}
 |(V^{R_1},U^{R_1},\Theta^{R_1})(t,x)-(v_-,u_-,\theta_-)|\leq Ce^{-\frac{2|x-\lambda_{1+}(t+t_0)|}{\sigma}},\\[2mm]
 |(V^{R_1},U^{R_1},\Theta^{R_1})_x(t,x)|\leq
\frac{C}{\sigma}e^{-\frac{2|x-\lambda_{1+}(t+t_0)|}{\sigma}};
\end{array}
$$
If $x\leq \lambda_{3-}(t+t_0)$, then
$$
\begin{array}{l}
 |(V^{R_3},U^{R_3},\Theta^{R_3})(t,x)-(v_+,u_+,\theta_+)|\leq Ce^{-\frac{2|x-\lambda_{3-}(t+t_0)|}{\sigma}},\\[2mm]
 |(V^{R_3},U^{R_3},\Theta^{R_3})_x(t,x)|\leq
\frac{C}{\sigma}e^{-\frac{2|x-\lambda_{3-}(t+t_0)|}{\sigma}};
\end{array}
$$

\item[(4)] There exist positive constants $C$ and $\sigma_0$ such that
for $\sigma\in(0,\sigma_0)$ and $t,t_0>0,$
$$
\sup_{x\in\mathbf{R}}|(V^{R_i},U^{R_i},
\Theta^{R_i})(t,x)-(v^{r_i},u^{r_i}, \theta^{r_i})(\frac xt)|\leq
\frac{C}{t}[\sigma\ln(1+t+t_0)+\sigma|\ln\sigma|+t_0].
$$
\end{enumerate}

\label{Theorem 3.1} There exist small positive constants
$\delta_1$ and $\varepsilon_1$ such that if the initial values and the
contact wave strength $\delta^{CD}$ satisfy
\begin{equation}
\mathcal{N}(\tau)|_{\tau=0}+\delta^{CD} \le \delta_1, \label{(4.9)}
\end{equation}
and the Knudsen number $\varepsilon$ satisfies $\varepsilon\leq \varepsilon_1$, then the
problem (\ref{(2.24)}) admits a unique global solution
$(v^\varepsilon,u^\varepsilon,\theta^\varepsilon)(\tau,y)$ satisfying
\begin{equation}
\begin{array}{l}
\displaystyle
\sup_{\tau,y}|(v^\varepsilon,u^\varepsilon,\theta^\varepsilon)(\tau,y)-(V,U,\Theta)(\tau,y)|\leq
C\varepsilon^{\frac15}.\\
\end{array}
\label{(4.10)}
\end{equation}
Here $\mathcal{N}(\tau)$ is defined by \eqref{(3.3+)} below.

\label{Lemma 3.3} There exists a constant $C>0$ such that
if $\delta^{CD}$ and $\varepsilon_0$ are small enough, then we have
\begin{equation}
\begin{array}{ll}
&\displaystyle \int_0^\tau\int_{{\bf R}}\varepsilon(1+\varepsilon\tau)^{-1}e^{-\frac{C_0\varepsilon
y^2}{1+\varepsilon\tau}} |(\phi,\psi,\zeta)|^2 dy
d\tau\\[3mm]
&\displaystyle  \leq
C\|(\phi,\psi,\zeta)(\tau,\cdot)\|^2+C\int_0^\tau\|(\phi_y,\psi_y,\zeta_y)\|^2d\tau\\
&\displaystyle +C\int_0^\tau (\tau+\tau_0)^{-\frac{3}{2}}\|(\phi,\psi,\zeta)\|^2
d\tau+C\varepsilon^{\frac25}.
\end{array}\label{(3.33)}
\end{equation}

\label{Theorem 4.1} There exist two small positive
constants $\delta_1$, $\varepsilon_1$, and a global\break Maxwellian
$\mathbf{M}_\star=\mathbf{M}_{[v_\star,u_\star,\theta_\star]}$ such that if
the initial data and the strength of the contact wave  $\delta^{CD}$
satisfy
\begin{equation}
\mathcal{N}(\tau)|_{\tau=0}+\delta^{CD} \le \delta_1, \label{(4.9)}
\end{equation}
and the Knudsen number  $\varepsilon\leq \varepsilon_1$, then the problem
(\ref{(2.52)}) admits a unique global solution $f^\varepsilon(\tau,y,\xi)$
satisfying
\begin{equation}
\begin{array}{l}
\displaystyle
\sup_{\tau,y}\|f^\varepsilon(\tau,y,\xi)-\mathbf{M}_{[V,U,\Theta]}(\tau,y,\xi)
\|_{L^2_{\xi}(\frac{1}{\sqrt{\mathbf{M}_\star}})}\le
C\varepsilon^{\frac15}.\\
\end{array}
\label{(4.10)}
\end{equation}
Here, $\mathcal{N}(\tau)$ is defined by \eqref{(4.11)} below.

If we choose the initial data for the Boltzmann equation
(\ref{(2.52)}) as
\begin{equation}
f^\varepsilon(0,y,\xi)=\mathbf{M}_{[V,U,\Theta]}(0,y,\xi)=\mathbf{M}_{[V(0,y),U(0,y),\Theta(0,y)]}(\xi),
\label{(4.12)}
\end{equation}
then
\begin{equation}
\mathcal{N}(\tau)|_{\tau=0}=O(1)\bigg[\|(\Theta_y,U_y)\|^2+\|(V_{yy},\Theta_{yy},U_{yy})\|^2\bigg]\bigg|_{\tau=0}=O(1)\varepsilon^{\frac12}.
\label{(4.13)}
\end{equation}
In this case, the functional measuring the perturbation
$\mathcal{N}(\tau)$ at $\tau=0$ is smaller than the estimate given
in Theorem \ref{Theorem 4.1} that is of the order of $O(\varepsilon^{\frac25})$
because $\varepsilon$ is small.
